import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listMyInvitedSpacesHandler } from "../handlers/listMyInvitedSpacesHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listMyInvitedSpacesHandler>>;

export function useListMyInvitedSpaces(
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listMyInvitedSpaces", bookmark],
    queryFn: () => listMyInvitedSpacesHandler(bookmark),
    ...options,
  });
}
